  it('standard reimbursement minus deductible', () => {
    expect(new Policy([sword()]).claim([{ itemType: 'sword', amount: 500 }])).toBe(400);
    expect(new Policy([{ type: 'rune' }]).claim([{ itemType: 'rune', amount: 200 }])).toBe(100);
  });

